            "options": [
                {
                    "label": "A",
                    "text": "$15.5\\text{ s}$",
                    "is_correct": false
                },
                {
                    "label": "B",
                    "text": "$30.0\\text{ s}$",
                    "is_correct": false
                },
                {
                    "label": "C",
                    "text": "$27.7\\text{ s}$",
                    "is_correct": true
                },
                {
                    "label": "D",
                    "text": "$20.0\\text{ s}$",
                    "is_correct": false
                }
            ],
            "solution": {
                "steps": [
                    {
                        "title": "Write Response Equation",
                        "content": "For a first-order step response, $T(t) = T_\\infty + (T_i - T_\\infty)e^{-t/\\tau}$."
                    },
                    {
                        "title": "Substitute Known Values",
                        "content": "$95 = 100 + (20 - 100)e^{-t/10} \\implies -5 = -80 e^{-t/10}$."
                    },
                    {
                        "title": "Solve for Time",
                        "content": "$e^{-t/10} = \\frac{5}{80} = 0.0625$. Taking the natural log, $-t/10 = \\ln(0.0625) \\approx -2.772$. Thus, $t = 27.72\\text{ s}$."
                    }
                ],
                "solution_image": "",
                "video_explanation": "",
                "final_answer": "C"
            },
